func (v TransactionOperationsView) At(i int) (OperationView, error) {
	var zero OperationView
	count, err := arrayViewCount([]byte(v), 100)
	if err != nil {
		return zero, err
	}
	if i < 0 || i >= count {
		return zero, viewErrIndexOutOfRange(0, i, count)
	}
	off, err := arrayTraverse([]byte(v), i, 4, func(d []byte) (int, error) { return OperationView(d).size(0) })
	if err != nil {
		return zero, err
	}
	if off >= len(v) {
		return zero, viewErrShortBuffer(uint32(off), "element offset exceeds data")
	}
	return OperationView(v[off:]), nil
}

// TransactionOperationsViewCursor is the Scan() cursor over TransactionOperationsView. It is returned by value: plain loops allocate nothing.
type TransactionOperationsViewCursor struct {
	buf   []byte
	off   int
	count int
	index int
	elem  OperationFields
	valid bool
	err   error
}

// Scan returns a by-value cursor over the array's elements. The wire count is validated against the buffer at construction.
func (v TransactionOperationsView) Scan() TransactionOperationsViewCursor {
	count, err := arrayViewCountChecked([]byte(v), 100, 8)
	return TransactionOperationsViewCursor{buf: []byte(v), off: 4, count: count, index: -1, err: err}
}

// Next advances to the next element, walking it once and capturing what Elem()/Bytes() need. Returns false at end or on error.
func (c *TransactionOperationsViewCursor) Next() bool {
	c.valid = false
	if c.err != nil || c.index+1 >= c.count {
		return false
	}
	if uint(c.off) > uint(len(c.buf)) {
		c.err = viewErrShortBuffer(uint32(c.off), "element offset exceeds data")
		return false
	}
	fields, err := locateOperation(OperationView(c.buf[c.off:]))
	if err != nil {
		c.err = err
		return false
	}
	c.elem = fields
	c.off += len(fields.View)
	c.index++
	c.valid = true
	return true
}

// Count returns the validated element count, safe for preallocation.
func (c *TransactionOperationsViewCursor) Count() int { return c.count }

// Index returns the 0-based position of the current element, or -1 before the first Next().
func (c *TransactionOperationsViewCursor) Index() int { return c.index }

// Elem returns the current element. Before the first Next(), after Next() returns false,
// or after an error, it returns the zero value and arms a sticky misuse error.
func (c *TransactionOperationsViewCursor) Elem() OperationFields {
	if !c.valid {
		c.armMisuse()
		var zero OperationFields
		return zero
	}
	return c.elem
}

// Bytes returns the current element's exact wire bytes (captured during Next, zero cost). Same misuse contract as Elem().
func (c *TransactionOperationsViewCursor) Bytes() []byte {
	if !c.valid {
		c.armMisuse()
		return nil
	}
	return []byte(c.elem.View)
}

// Err returns the first error encountered, if any.
func (c *TransactionOperationsViewCursor) Err() error { return c.err }
func (c *TransactionOperationsViewCursor) armMisuse() {
	if c.err == nil {
		c.err = errCursorMisuse
	}
}

